import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaCalendarAlt, FaBookOpen, FaGraduationCap, FaPhone, FaEnvelope, FaMapMarkerAlt, FaFacebook, FaTwitter, FaLinkedin, FaInstagram } from 'react-icons/fa';
import '../App.css';
import '../styles/Home.css';

const Home = () => {
    const navigate = useNavigate();
    const [date] = useState(new Date());
    const [visits, setVisits] = useState([]);

    // Merge default courses with custom ones from localStorage
    const [courses, setCourses] = useState(() => {
        const defaults = [
            { id: 1, title: "B.Sc Information Technology", description: "Learn software development, networking, and database management." },
            { id: 2, title: "Management Marketing", description: "Master strategies for brand management and market analysis." },
            { id: 3, title: "Finance Management", description: "Understand financial planning, investment strategies, and corporate finance." },
            { id: 4, title: "B.Commerce", description: "Comprehensive study of business, accounting, and economics." }
        ];
        const saved = localStorage.getItem('customCourses');
        const custom = saved ? JSON.parse(saved) : [];
        return [...defaults, ...custom];
    });

    useEffect(() => {
        const savedVisits = JSON.parse(localStorage.getItem('websiteVisits') || '[]');
        const now = new Date();
        const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

        if (!savedVisits.includes(today)) {
            const updatedVisits = [...savedVisits, today];
            localStorage.setItem('websiteVisits', JSON.stringify(updatedVisits));
            setVisits(updatedVisits);
        } else {
            setVisits(savedVisits);
        }
    }, []);

    const [showCourses, setShowCourses] = useState(false);
    const [showEnroll, setShowEnroll] = useState(false);
    const [hoveredCourseId, setHoveredCourseId] = useState(null);

    // Simple Calendar Helpers
    const daysInMonth = (month, year) => new Date(year, month + 1, 0).getDate();
    const firstDayOfMonth = (month, year) => new Date(year, month, 1).getDay();

    const renderCalendar = () => {
        const month = date.getMonth();
        const year = date.getFullYear();
        const days = daysInMonth(month, year);
        const firstDay = firstDayOfMonth(month, year);

        const calendarDays = [];

        for (let i = 0; i < firstDay; i++) {
            calendarDays.push(<div key={`empty-${i}`} className="calendar-day-empty"></div>);
        }

        for (let i = 1; i <= days; i++) {
            const isToday = i === new Date().getDate() && month === new Date().getMonth();
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
            const isVisited = visits.includes(dateStr);

            calendarDays.push(
                <div key={i} className={`calendar-day ${isToday ? 'today' : ''} ${isVisited ? 'visited' : ''}`}>
                    {i}
                    {isVisited && <span className="visit-dot"></span>}
                </div>
            );
        }

        return calendarDays;
    };

    const handleEnroll = (courseTitle) => {
        localStorage.setItem('selectedCourse', courseTitle);
        navigate('/signup');
    };

    return (
        <div className={`page-container ${(showCourses || showEnroll) ? 'content-focused' : ''}`}>
            {/* Top Header Section */}
            <header className="header">
                <div className="logo-container">
                    <FaGraduationCap className="logo-icon" />
                    <span className="logo-text">E-LEARN</span>
                </div>
                <div className="header-content">
                    <h1 className="college-name">VIVEK COLLEGE OF COMMERCE</h1>
                    <h3 className="sub-text">(Autonomous)</h3>
                    <div className="auth-params">
                        <button onClick={() => navigate('/login')} className="login-btn">Login / Sign Up</button>
                    </div>
                </div>
            </header>

            {/* Main Content */}
            <div className="main-content">

                <div className="left-column">
                    {/* Courses Dropdown Section (View Only) */}
                    <div
                        className={`dropdown-container ${showEnroll ? 'blurred' : ''}`}
                        onMouseEnter={() => setShowCourses(true)}
                        onMouseLeave={() => setShowCourses(false)}
                    >
                        <button className="dropdown-button">
                            <FaBookOpen style={{ marginRight: '10px' }} />
                            View Our Courses
                        </button>

                        {showCourses && (
                            <div className="dropdown-menu">
                                {courses.map(course => (
                                    <div
                                        key={course.id}
                                        className={`dropdown-item ${hoveredCourseId === course.id ? 'hovered' : ''}`}
                                        onMouseEnter={() => setHoveredCourseId(course.id)}
                                        onMouseLeave={() => setHoveredCourseId(null)}
                                    >
                                        <div>{course.title}</div>
                                        {hoveredCourseId === course.id && (
                                            <div className="course-description">
                                                {course.description}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Enroll Dropdown Section */}
                    <div
                        className={`dropdown-container ${showCourses ? 'blurred' : ''}`}
                        onMouseEnter={() => setShowEnroll(true)}
                        onMouseLeave={() => setShowEnroll(false)}
                        style={{ marginTop: '20px' }}
                    >
                        <button className="dropdown-button enroll-dropdown-btn">
                            <FaGraduationCap style={{ marginRight: '10px' }} />
                            Enroll in a Course
                        </button>

                        {showEnroll && (
                            <div className="dropdown-menu">
                                {courses.map(course => (
                                    <div
                                        key={course.id}
                                        className="dropdown-item enroll-item"
                                        onClick={() => handleEnroll(course.title)}
                                    >
                                        <div>{course.title}</div>
                                        <span className="enroll-hint">Click to Register</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Calendar Section Wrapper */}
                <div className="right-column">
                    <h2 className="section-title">
                        <FaCalendarAlt style={{ marginRight: '10px' }} />
                        Academic Calendar - {date.toLocaleString('default', { month: 'long' })} {date.getFullYear()}
                    </h2>
                    <div className="calendar-container">
                        <div className="week-days">
                            <div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div>
                        </div>
                        <div className="calendar-grid">
                            {renderCalendar()}
                        </div>
                    </div>
                </div>

            </div>

            {/* Footer Section */}
            <footer className="footer">
                <div className="footer-content">
                    <div className="footer-section">
                        <h4>Contact Us</h4>
                        <p><FaMapMarkerAlt /> Siddharth Nagar, Goregaon (W), Mumbai 400104</p>
                        <p><FaPhone /> 022 2872 4058</p>
                        <p><FaEnvelope /> vivekcollege@gmail.com</p>
                    </div>
                    <div className="footer-section">
                        <h4>Quick Links</h4>
                        <ul>
                            <li onClick={() => navigate('/')}>Home</li>
                            <li onClick={() => navigate('/login')}>Login / Sign Up</li>
                            <li onClick={() => navigate('/student')}>Student Portal</li>
                        </ul>
                    </div>
                    <div className="footer-section">
                        <h4>Follow Us</h4>
                        <div className="social-links">
                            <FaFacebook className="social-icon" />
                            <FaTwitter className="social-icon" />
                            <FaLinkedin className="social-icon" />
                            <FaInstagram className="social-icon" />
                        </div>
                    </div>
                </div>
                <div className="footer-bottom">
                    &copy; {new Date().getFullYear()} Vivek College of Commerce. All Rights Reserved.
                </div>
            </footer>
        </div>
    );
};

export default Home;
